<?php
require '../config/config.php';role(['administrator','pustakawan']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$id=(int)($_POST['id']??0);$code=trim($_POST['copy_code']??'');if($code){$q=$pdo->prepare("SELECT l.id FROM loans l JOIN copies c ON c.id=l.copy_id WHERE c.code=? AND l.returned_at IS NULL");$q->execute([$code]);$id=(int)$q->fetchColumn();if(!$id)throw new Exception('Barcode buku tidak sedang dipinjam.');}$s=$pdo->prepare('SELECT * FROM loans WHERE id=? AND returned_at IS NULL');$s->execute([$id]);$l=$s->fetch();if(!$l)throw new Exception('Transaksi tidak ditemukan.');$d=$l['due_date']<date('Y-m-d')?(new DateTime($l['due_date']))->diff(new DateTime(date('Y-m-d')))->days:0;$f=$d*(int)setting('fine_per_day',500);$pdo->beginTransaction();$pdo->prepare('UPDATE loans SET returned_at=NOW(),late_days=?,fine=? WHERE id=?')->execute([$d,$f,$l['id']]);$pdo->prepare("UPDATE copies SET status='tersedia' WHERE id=?")->execute([$l['copy_id']]);$pdo->commit();setmsg("Dikembalikan. Terlambat $d hari, denda Rp".number_format($f,0,',','.'));}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();setmsg($e->getMessage(),'danger');}}
$r=$pdo->query("SELECT l.id,l.due_date,u.name,c.code,b.title FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE l.returned_at IS NULL ORDER BY l.due_date")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Pengembalian</title><link rel=stylesheet href=../public/style.css></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>📥 Pengembalian</h1><?php msg()?><div class=form><h3>⚡ Pengembalian Cepat dengan Barcode</h3><form method=post><label>Scan Barcode Eksemplar</label><input name=copy_code autofocus placeholder="Contoh: BK-0001-01" required><button>↩️ Proses Pengembalian</button></form></div><br><table class=table><tr><th>Anggota</th><th>Buku</th><th>Jatuh Tempo</th><th>Status</th><th>Aksi</th></tr><?php foreach($r as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['code'].' - '.$x['title'])?></td><td><?=e($x['due_date'])?></td><td><?=$x['due_date']<date('Y-m-d')?'🔴 Terlambat':'🟢 Tepat waktu'?></td><td><form method=post><input type=hidden name=id value=<?=$x['id']?>><button class=green>Kembalikan</button></form></td></tr><?php endforeach?><?php if(!$r):?><tr><td colspan=5>Tidak ada peminjaman aktif.</td></tr><?php endif?></table></main></div></body></html>
